import sys

def solve():
    # Read input from stdin
    input_data = sys.stdin.read().split()

    if not input_data:
        return

    X = int(input_data[0])

    # Calculate the sum of numbers in the 9x9 multiplication table excluding X
    total_sum = 0
    for i in range(1, 10):
        for j in range(1, 10):
            val = i * j
            if val != X:
                total_sum += val

    print(total_sum)

if __name__ == '__main__':
    solve()

import sys

def main():
    # Read all input from stdin
    input_data = sys.stdin.read().split()

    if not input_data:
        return

    iterator = iter(input_data)

    try:
        # Read N and D
        N = int(next(iterator))
        D = int(next(iterator))

        # Read the snakes' data
        snakes = []
        for _ in range(N):
            T = int(next(iterator))
            L = int(next(iterator))
            snakes.append((T, L))

        # Iterate for each k from 1 to D
        for k in range(1, D + 1):
            max_weight = 0
            # Calculate weight for each snake with increased length (L + k)
            for T, L in snakes:
                weight = T * (L + k)
                if weight > max_weight:
                    max_weight = weight
            print(max_weight)

    except StopIteration:
        pass

if __name__ == '__main__':
    main()
